public class FirstOrderFunctionAnalyzer_visit_TriageGen1Test {

    private FirstOrderFunctionAnalyzer analyzer;

    @Mock private NodeTraversal t;
    @Mock private Node n;
    @Mock private Node parent;
    @Mock private Node rootNode;
    @Mock private Scope scope;
    @Mock private Scope ownerScope;
    @Mock private Var var;
    @Mock private DataRecord dataRecord;
    @Mock private java.util.Map<Scope, DataRecord> dataMap;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // The analyzer uses a 'data' field. Since it's not provided in the snippet, 
        // we assume it's a field in the class. In a real scenario, we'd use reflection 
        // or a protected constructor if available. Here we simulate the environment.
        analyzer = new FirstOrderFunctionAnalyzer(dataMap);
    }

    @Test
    public void testVisit_InGlobalScope_ReturnsEarly() {
        when(t.inGlobalScope()).thenReturn(true);
        analyzer.visit(t, n, parent);
        verify(n, never()).isReturn();
    }

    @Test
    public void testVisit_NonEmptyReturn_RecordsNonEmptyReturn() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(mock(Node.class));
        when(t.getScopeRoot()).thenReturn(ownerScope);
        when(dataMap.get(ownerScope)).thenReturn(dataRecord);

        analyzer.visit(t, n, parent);
        verify(dataRecord).recordNonEmptyReturn();
    }

    @Test
    public void testVisit_NonEmptyReturn_WithNullChild_DoesNotRecord() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(null);

        analyzer.visit(t, n, parent);
        verify(dataMap, never()).get(any());
    }

    @Test
    public void testVisit_ScopeDepthTooLow_ReturnsEarly() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(false);
        when(t.getScopeDepth()).thenReturn(2);

        analyzer.visit(t, n, parent);
        verify(t, never()).getScope();
    }

    @Test
    public void testVisit_IsName_LValue_NotBleeding_LocalAssignment() {
        setupScopeDepth(3);
        when(n.isName()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(true);
        // Mocking static NodeUtil calls requires Mockito-inline or a wrapper. 
        // Assuming NodeUtil is accessible.
        when(NodeUtil.isBleedingFunctionName(n)).thenReturn(false);
        when(n.getString()).thenReturn("myVar");
        when(t.getScope()).thenReturn(scope);
        when(scope.getVar("myVar")).thenReturn(var);
        when(var.getScope()).thenReturn(ownerScope);
        when(ownerScope.isLocal()).thenReturn(true);
        when(ownerScope.getRootNode()).thenReturn(rootNode);
        when(dataMap.get(rootNode)).thenReturn(dataRecord);

        // Case 1: scope == ownerScope (Local assignment)
        when(scope.equals(ownerScope)).thenReturn(true);
        analyzer.visit(t, n, parent);
        verify(dataRecord).recordAssignedName("myVar");

        // Case 2: scope != ownerScope (Escaped var)
        when(scope.equals(ownerScope)).thenReturn(false);
        analyzer.visit(t, n, parent);
        verify(dataRecord).recordEscapedVarName("myVar");
    }

    @Test
    public void testVisit_IsName_BleedingFunction_DoesNothing() {
        setupScopeDepth(3);
        when(n.isName()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(true);
        when(NodeUtil.isBleedingFunctionName(n)).thenReturn(true);

        analyzer.visit(t, n, parent);
        verify(t, never()).getScope();
    }

    @Test
    public void testVisit_IsGetProp_Unscoped_LValue_EscapedQualified() {
        setupScopeDepth(3);
        when(n.isName()).thenReturn(false);
        when(n.isGetProp()).thenReturn(true);
        when(n.isUnscopedQualifiedName()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(true);

        Node rootOfQualified = mock(Node.class);
        when(NodeUtil.getRootOfQualifiedName(n)).thenReturn(rootOfQualified);
        when(rootOfQualified.getString()).thenReturn("propName");
        when(n.getQualifiedName()).thenReturn("obj.propName");

        when(t.getScope()).thenReturn(scope);
        when(scope.getVar("propName")).thenReturn(var);
        when(var.getScope()).thenReturn(ownerScope);
        when(ownerScope.isLocal()).thenReturn(true);
        when(scope.equals(ownerScope)).thenReturn(false);
        when(ownerScope.getRootNode()).thenReturn(rootNode);
        when(dataMap.get(rootNode)).thenReturn(dataRecord);

        analyzer.visit(t, n, parent);
        verify(dataRecord).recordEscapedQualifiedName("obj.propName");
    }

    @Test
    public void testVisit_IsGetProp_NotLValue_DoesNothing() {
        setupScopeDepth(3);
        when(n.isName()).thenReturn(false);
        when(n.isGetProp()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(false);

        analyzer.visit(t, n, parent);
        verify(t, never()).getScope();
    }

    private void setupScopeDepth(int depth) {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(false);
        when(t.getScopeDepth()).thenReturn(depth);
    }

    /**
     * Helper class to simulate the internal data structure of the analyzer.
     */
    private static class FirstOrderFunctionAnalyzer extends com.google.javascript.jscomp.TypedScopeCreator.FirstOrderFunctionAnalyzer {
        private final java.util.Map<Scope, DataRecord> data;

        public FirstOrderFunctionAnalyzer(java.util.Map<Scope, DataRecord> data) {
            this.data = data;
        }
    }

    private interface DataRecord {
        void recordNonEmptyReturn();
        void recordAssignedName(String name);
        void recordEscapedVarName(String name);
        void recordEscapedQualifiedName(String name);
    }
}

// Mocking interfaces for Node as the original code uses complex types
interface Node {
    boolean isReturn();
    Node getFirstChild();
    boolean isName();
    boolean isGetProp();
    boolean isUnscopedQualifiedName();
    String getString();
    String getQualifiedName();
}
